public class Element_hasClass_TriageGen0Test {

    @Test
    public void test_hasClass_Null() {
        Element element = new Element(Tag.valueOf("div"));
        element.attributes().put("class", "test");
        assertFalse(element.hasClass(null));
        assertEquals(1, element.attributes().size());
    }

    @Test
    public void test_hasClass_EmptyString() {
        Element element = new Element(Tag.valueOf("div"));
        element.attributes().put("class", "test");
        assertTrue(element.hasClass(""));
        assertEquals(1, element.attributes().size());
    }

    @Test
    public void test_hasClass_NullClass() {
        Element element = new Element(Tag.valueOf("div"));
        assertFalse(element.hasClass("test"));
        assertEquals(0, element.attributes().size());
    }

    @Test
    public void test_hasClass_SameLength() {
        Element element = new Element(Tag.valueOf("div"));
        element.attributes().put("class", "test");
        assertTrue(element.hasClass("test"));
        assertEquals(1, element.attributes().size());
    }

    @Test
    public void test_hasClass_LargerLength() {
        Element element = new Element(Tag.valueOf("div"));
        element.attributes().put("class", "test-class-123");
        assertTrue(element.hasClass("test-class-"));
        assertEquals(1, element.attributes().size());
    }

    @Test
    public void test_hasClass_SmallerLength() {
        Element element = new Element(Tag.valueOf("div"));
        element.attributes().put("class", "test-class-123");
        assertTrue(element.hasClass("test"));
        assertEquals(1, element.attributes().size());
    }

    @Test
    public void test_hasClass_Whitespace() {
        Element element = new Element(Tag.valueOf("div"));
        element.attributes().put("class", " test-123 ");
        assertTrue(element.hasClass("test"));
        assertEquals(1, element.attributes().size());
    }

    @Test
    public void test_hasClass_MultiWhitespace() {
        Element element = new Element(Tag.valueOf("div"));
        element.attributes().put("class", " test-123 - test - 456 ");
        assertTrue(element.hasClass("test"));
        assertEquals(1, element.attributes().size());
    }

    @Test
    public void test_hasClass_MultiClass() {
        Element element = new Element(Tag.valueOf("div"));
        element.attributes().put("class", "test-class-123 test-class-456");
        assertTrue(element.hasClass("test-class-"));
        assertEquals(1, element.attributes().size());
    }
}
